# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">HOMEOSTAZİ (İÇ DENGE) VE UYARILARA TEPKİ MEKANİZMASI</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">HOMEOSTAZİ (KARARLI İÇ DENGE)</text>\n  <text x="42" y="96" font-size="11.5" font-weight="bold" fill="#1e3a8a">• Vücut Sıcaklığının Korunması (~36,5 °C):</text>\n  <text x="52" y="114" font-size="10.5" fill="#334155">Sıcakta terleme, soğukta titreme ve damar daralması.</text>\n  <text x="42" y="140" font-size="11.5" font-weight="bold" fill="#1e3a8a">• Kan pH Değerinin Sabit Tutulması (~7,4):</text>\n  <text x="52" y="158" font-size="10.5" fill="#334155">Solunumla CO₂ atımı ve böbreklerle iyon dengesi.</text>\n  <text x="42" y="184" font-size="11.5" font-weight="bold" fill="#1e3a8a">• Su, Mineral ve Kan Şekeri Dengesi:</text>\n  <text x="52" y="202" font-size="10.5" fill="#334155">İnsülin-glukagon hormonları ve boşaltım faaliyetleri.</text>\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">UYARILARA TEPKİ VE BOŞALTIM</text>\n  <text x="377" y="96" font-size="11.5" font-weight="bold" fill="#14532d">• Uyarılara Tepki Örnekleri:</text>\n  <text x="387" y="114" font-size="10.5" fill="#334155">- Öglena\'nın ışığa yönelmesi (pozitif fototaksi)</text>\n  <text x="387" y="132" font-size="10.5" fill="#334155">- Küstüm otunun dokununca yaprak kapatması</text>\n  <text x="377" y="160" font-size="11.5" font-weight="bold" fill="#14532d">• Boşaltım ve Homeostazi İlişkisi:</text>\n  <text x="387" y="178" font-size="10.5" fill="#334155">- Tatlı su tek hücrelilerinde kontraktil koful</text>\n  <text x="387" y="196" font-size="10.5" fill="#334155">- Bitkilerde terleme, damlama (gutasyon), yaprak dökümü</text>\n  <text x="517" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Tüm sistemler homeostaziyi korumak için birlikte çalışır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">BÜYÜME-GELİŞME, ÜREME ÇEŞİTLERİ VE ADAPTASYON</text>\n  <rect x="25" y="45" width="205" height="195" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="127" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#854d0e">BÜYÜME VE GELİŞME</text>\n  <text x="38" y="96" font-size="11" font-weight="bold" fill="#713f12">• Tek Hücrelilerde Büyüme:</text>\n  <text x="45" y="113" font-size="10.5" fill="#334155">Sitoplazma hacmi ve kütlesi artışı.</text>\n  <text x="38" y="138" font-size="11" font-weight="bold" fill="#713f12">• Çok Hücrelilerde Büyüme:</text>\n  <text x="45" y="155" font-size="10.5" fill="#334155">Hücre bölünmesi (sayı artışı) ve</text>\n  <text x="45" y="170" font-size="10.5" fill="#334155">hücre kütlesinin artması.</text>\n  <text x="38" y="195" font-size="11" font-weight="bold" fill="#713f12">• Gelişme:</text>\n  <text x="45" y="212" font-size="10.5" fill="#334155">Doku ve organların işlev kazanması.</text>\n  <rect x="247" y="45" width="205" height="195" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">ÜREME (NESLİN DEVAMI)</text>\n  <text x="260" y="96" font-size="11" font-weight="bold" fill="#581c87">• Eşeysiz Üreme:</text>\n  <text x="267" y="113" font-size="10.5" fill="#334155">Tek ata, genetik kopya bireyler</text>\n  <text x="267" y="128" font-size="10.5" fill="#334155">(bölünme, tomurcuklanma vb.).</text>\n  <text x="260" y="155" font-size="11" font-weight="bold" fill="#581c87">• Eşeyli Üreme:</text>\n  <text x="267" y="172" font-size="10.5" fill="#334155">Üreme hücreleri ve döllenme;</text>\n  <text x="267" y="187" font-size="10.5" fill="#334155">kalıtsal çeşitlilik (varyasyon) sağlar.</text>\n  <text x="350" y="218" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#7e22ce">Bireyin yaşaması için şart değildir!</text>\n  <rect x="470" y="45" width="205" height="195" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="572" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">VARYASYON VE ADAPTASYON</text>\n  <text x="483" y="96" font-size="11" font-weight="bold" fill="#7c2d12">• Varyasyon:</text>\n  <text x="490" y="113" font-size="10.5" fill="#334155">Tür içi kalıtsal çeşitlilik.</text>\n  <text x="483" y="138" font-size="11" font-weight="bold" fill="#7c2d12">• Adaptasyon (Uyum):</text>\n  <text x="490" y="155" font-size="10.5" fill="#334155">Yaşama ve üreme şansını artıran</text>\n  <text x="490" y="170" font-size="10.5" fill="#334155">kalıtsal özellikler (kaktüs dikeni,</text>\n  <text x="490" y="185" font-size="10.5" fill="#334155">kutup ayısının post ve yağ tabakası).</text>\n  <text x="572" y="218" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#c2410c">Kalıtsaldır, nesilden nesile aktarılır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ÇOK HÜCRELİ CANLILARDA ORGANİZASYON BASAMAKLARI</text>\n  <rect x="25" y="55" width="95" height="60" rx="8" fill="#e0f2fe" stroke="#0284c7" stroke-width="2"/>\n  <text x="72" y="82" text-anchor="middle" font-size="12" font-weight="bold" fill="#0369a1">1. Atom ve</text>\n  <text x="72" y="98" text-anchor="middle" font-size="12" font-weight="bold" fill="#0369a1">Molekül</text>\n  <text x="130" y="90" font-size="16" font-weight="bold" fill="#64748b">→</text>\n  <rect x="145" y="55" width="95" height="60" rx="8" fill="#bae6fd" stroke="#0284c7" stroke-width="2"/>\n  <text x="192" y="88" text-anchor="middle" font-size="12" font-weight="bold" fill="#0369a1">2. Organel</text>\n  <text x="250" y="90" font-size="16" font-weight="bold" fill="#64748b">→</text>\n  <rect x="265" y="55" width="105" height="60" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="2.5"/>\n  <text x="317" y="82" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">3. HÜCRE</text>\n  <text x="317" y="98" text-anchor="middle" font-size="10" fill="#166534">(Canlılık başlar)</text>\n  <text x="380" y="90" font-size="16" font-weight="bold" fill="#64748b">→</text>\n  <rect x="395" y="55" width="85" height="60" rx="8" fill="#fef08a" stroke="#ca8a04" stroke-width="2"/>\n  <text x="437" y="88" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">4. Doku</text>\n  <text x="490" y="90" font-size="16" font-weight="bold" fill="#64748b">→</text>\n  <rect x="505" y="55" width="80" height="60" rx="8" fill="#fed7aa" stroke="#ea580c" stroke-width="2"/>\n  <text x="545" y="88" text-anchor="middle" font-size="12" font-weight="bold" fill="#9a3412">5. Organ</text>\n  <text x="592" y="90" font-size="16" font-weight="bold" fill="#64748b">→</text>\n  <rect x="605" y="55" width="75" height="60" rx="8" fill="#fecaca" stroke="#dc2626" stroke-width="2"/>\n  <text x="642" y="82" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#991b1b">6. Sistem</text>\n  <text x="642" y="98" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#991b1b">7. Organizma</text>\n  <rect x="25" y="138" width="655" height="100" rx="10" fill="#f1f5f9" stroke="#94a3b8" stroke-width="1.5"/>\n  <text x="45" y="164" font-size="12" font-weight="bold" fill="#0f172a">• Tek Hücreli Canlılarda (Bakteri, Amip, Öglena): Atom → Molekül → Organel → Hücre (Organizma)</text>\n  <text x="45" y="190" font-size="12" font-weight="bold" fill="#0f172a">• Çok Hücreli Canlılarda (Bitki, Hayvan): Hücre → Doku → Organ → Sistem → Organizma</text>\n  <text x="45" y="216" font-size="11.5" fill="#334155">• Bilimsel Gözlem ve Kayıt: Canlıların bu ortak özellikleri nicel ve nitel gözlem tablolarıyla kaydedilir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
